  TYPE t_order_tab IS TABLE OF orders%ROWTYPE;
  l_orders t_order_tab;
BEGIN
  SELECT *
    BULK COLLECT INTO l_orders
    FROM orders
   ORDER BY order_id;

  DBMS_OUTPUT.PUT_LINE('Rows fetched: ' || l_orders.COUNT);
  DBMS_OUTPUT.PUT_LINE('Last amount: ' || l_orders(l_orders.COUNT).amount);
END;
/

DECLARE
  TYPE t_order_tab IS TABLE OF orders%ROWTYPE;
  l_orders t_order_tab;
BEGIN
  SELECT *
    BULK COLLECT INTO l_orders
    FROM orders
   WHERE status = 'CANCELLED';

  IF l_orders.COUNT = 0 THEN
    DBMS_OUTPUT.PUT_LINE('No cancelled orders');
  END IF;
END;
/

DECLARE
  CURSOR c_orders IS
    SELECT order_id, amount
      FROM orders
     ORDER BY order_id;

  TYPE t_order_tab IS TABLE OF c_orders%ROWTYPE;
  l_orders t_order_tab;
  l_batch  PLS_INTEGER := 0;
  l_total  NUMBER := 0;
BEGIN
  OPEN c_orders;
  LOOP
    FETCH c_orders BULK COLLECT INTO l_orders LIMIT 10;
    EXIT WHEN l_orders.COUNT = 0;

    l_batch := l_batch + 1;
    FOR i IN 1 .. l_orders.COUNT LOOP
      l_total := l_total + l_orders(i).amount;
    END LOOP;

    DBMS_OUTPUT.PUT_LINE('Batch ' || l_batch || ': ' ||
      l_orders.COUNT || ' rows, first id ' || l_orders(1).order_id);
  END LOOP;
  CLOSE c_orders;

  DBMS_OUTPUT.PUT_LINE('Total amount: ' || l_total);
END;
/

