DECLARE
  CURSOR c_shipped IS
    SELECT order_id, customer_id, amount, status
      FROM orders
     WHERE status = 'SHIPPED'
     ORDER BY order_id;

  TYPE t_ship_tab IS TABLE OF c_shipped%ROWTYPE;
  l_rows t_ship_tab;
BEGIN
  OPEN c_shipped;
  LOOP
    FETCH c_shipped BULK COLLECT INTO l_rows LIMIT 100;
    EXIT WHEN l_rows.COUNT = 0;

    FORALL i IN 1 .. l_rows.COUNT
      INSERT INTO order_archive (order_id, customer_id, amount, status)
      VALUES (l_rows(i).order_id, l_rows(i).customer_id,
              l_rows(i).amount, l_rows(i).status);

    DBMS_OUTPUT.PUT_LINE('Archived in this batch: ' || SQL%ROWCOUNT);
  END LOOP;
  CLOSE c_shipped;
  COMMIT;
END;
/

DECLARE
  TYPE t_id_tab IS TABLE OF orders.customer_id%TYPE;
  l_customers t_id_tab := t_id_tab(1, 3, 9);
BEGIN
  FORALL i IN 1 .. l_customers.COUNT
    UPDATE orders
       SET amount = amount + 10
     WHERE customer_id = l_customers(i);

  FOR i IN 1 .. l_customers.COUNT LOOP
    DBMS_OUTPUT.PUT_LINE('Customer ' || l_customers(i) ||
      ': ' || SQL%BULK_ROWCOUNT(i) || ' rows');
  END LOOP;
  DBMS_OUTPUT.PUT_LINE('Total: ' || SQL%ROWCOUNT);
  ROLLBACK;
END;
/

