DECLARE
  CURSOR c_shipped IS
    SELECT order_id, customer_id, amount, status
      FROM orders
     WHERE status = 'SHIPPED'
     ORDER BY order_id;

  TYPE t_ship_tab IS TABLE OF c_shipped%ROWTYPE;
  l_rows t_ship_tab;
  l_idx  PLS_INTEGER;

  e_bulk_errors EXCEPTION;
  PRAGMA EXCEPTION_INIT(e_bulk_errors, -24381);
BEGIN
  OPEN c_shipped;
  LOOP
    FETCH c_shipped BULK COLLECT INTO l_rows LIMIT 100;
    EXIT WHEN l_rows.COUNT = 0;

    BEGIN
      FORALL i IN 1 .. l_rows.COUNT SAVE EXCEPTIONS
        INSERT INTO order_archive (order_id, customer_id, amount, status)
        VALUES (l_rows(i).order_id, l_rows(i).customer_id,
                l_rows(i).amount, l_rows(i).status);
    EXCEPTION
      WHEN e_bulk_errors THEN
        FOR j IN 1 .. SQL%BULK_EXCEPTIONS.COUNT LOOP
          l_idx := SQL%BULK_EXCEPTIONS(j).ERROR_INDEX;
          DBMS_OUTPUT.PUT_LINE('Order ' || l_rows(l_idx).order_id ||
            ' failed: ORA-' ||
            LPAD(SQL%BULK_EXCEPTIONS(j).ERROR_CODE, 5, '0'));
        END LOOP;
    END;
  END LOOP;
  CLOSE c_shipped;
  COMMIT;
END;
/

